```js
// db.js
const { Pool } = require("pg");

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,

  max: 10,
  idleTimeoutMillis: 30_000,
  connectionTimeoutMillis: 5_000,
  query_timeout: 10_000,
  statement_timeout: 10_000,
});

pool.on("error", (err) => {
  console.error("Unexpected idle PostgreSQL client error:", err);
});

async function query(text, params) {
  const start = Date.now();

  try {
    const res = await pool.query(text, params);
    console.log("SQL ok", { ms: Date.now() - start, rows: res.rowCount });
    return res;
  } catch (err) {
    console.error("SQL failed", {
      ms: Date.now() - start,
      message: err.message,
      code: err.code,
    });
    throw err;
  }
}

async function shutdown() {
  console.log("Closing PostgreSQL pool...");
  await pool.end();
  console.log("PostgreSQL pool closed");
}

process.on("SIGINT", async () => {
  await shutdown();
  process.exit(0);
});

process.on("SIGTERM", async () => {
  await shutdown();
  process.exit(0);
});

module.exports = { pool, query, shutdown };
```

Use:

```js
const { query } = require("./db");

const { rows } = await query("select * from users where id = $1", [userId]);
```

Key bits: `connectionTimeoutMillis` limits acquiring a DB connection; `query_timeout` / `statement_timeout` limit long queries; `pool.on("error")` catches broken idle clients; `pool.end()` drains pool on shutdown.

