For transactions, always release clients:

```js
const { pool } = require("./db");

async function runTransaction() {
  const client = await pool.connect();

  try {
    await client.query("BEGIN");

    await client.query("INSERT INTO audit_log(message) VALUES ($1)", [
      "created",
    ]);

    await client.query("COMMIT");
  } catch (err) {
    await client.query("ROLLBACK");
    throw err;
  } finally {
    client.release();
  }
}
```

Key parts: `connectionTimeoutMillis` for connect timeout, `statement_timeout` / `query_timeout` for slow queries, `pool.on("error")` for idle-client failures, `pool.end()` on shutdown.

