```tsx
import React from "react";

type Props = {
  children: React.ReactNode;
  fallback?: (args: { error: Error; retry: () => void }) => React.ReactNode;
  onError?: (error: Error, info: React.ErrorInfo) => void;
};

type State = {
  error: Error | null;
  retryKey: number;
};

export class ErrorBoundary extends React.Component<Props, State> {
  state: State = { error: null, retryKey: 0 };

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { error };
  }

  componentDidCatch(error: Error, info: React.ErrorInfo) {
    this.props.onError?.(error, info);

    console.error("ErrorBoundary caught render error", {
      message: error.message,
      stack: error.stack,
      componentStack: info.componentStack,
    });
  }

  retry = () => {
    this.setState((state) => ({
      error: null,
      retryKey: state.retryKey + 1,
    }));
  };

  render() {
    const { error, retryKey } = this.state;

    if (error) {
      if (this.props.fallback) {
        return this.props.fallback({ error, retry: this.retry });
      }

      return (
        <div role="alert">
          <h2>Something went wrong.</h2>
          <p>{error.message}</p>
          <button type="button" onClick={this.retry}>
            Retry
          </button>
        </div>
      );
    }

    return <React.Fragment key={retryKey}>{this.props.children}</React.Fragment>;
  }
}
```

